fn is_ascii_digit(c: char) -> bool {
    // Check if the character is within the ASCII digit range '0' to '9'
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // For empty string, return true (vacuously true)
    // Check each character using is_ascii_digit
    s.chars().all(is_ascii_digit)
}